#include <iostream>
int main() {
    int x{};
    if (!(std::cin >> x)) { std::cout << "invalid\n"; return 0; }
    if (x < 0) { std::cout << "negative\n"; }
    else if (x == 0) { std::cout << "zero\n"; }
    else { std::cout << "positive\n"; }
}

#include <iostream>
int main() {
    int code{};
    if (!(std::cin >> code)) { std::cout << "invalid\n"; return 0; }
    switch (code) {
        case 1: std::cout << "open\n"; break;
        case 2: std::cout << "save\n"; break;
        default: std::cout << "unknown\n"; break;
    }
}

